// Doorway awareness index — record JAH-GPC-VIDEODOORBELL-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"res_mp": 4.0, "battery_days": 90, "price_usd": 180};
var value = (m.res_mp*m.battery_days/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-VIDEODOORBELL-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-VIDEODOORBELL-000001|' + value.toFixed(2) + ' awareness index');

